INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r10','白','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','哀公之子，谥戴公，在位三十四年，为春秋初年以前宋国在位时间较长之君，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋戴公"}]','戴公',NULL,'宋戴公','[]');
