INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r12','力','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武公之子，谥宣公，欲传位弟穆公和，临终仍以长子与夷嗣位，开宋国传弟之先河，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋宣公"}]','宣公',NULL,'宋宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r13','和','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','宣公弟子和，为报兄恩拒受传位，后受托孤而立殇公与夷，穆公托孤酿成日后政乱，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋穆公"}]','穆公',NULL,'宋穆公','[]');
