INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r15','冯','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','弑殇公自立，乘丘之战败鲁军、擒南宫长万又释归，前692年因博戏争执，为万弑于蒙泽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋庄公"}]','庄公',NULL,'宋庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r16','捷','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,-682,1,NULL,'year','["君主"]','宋闵公（子捷），宋庄公之子，前691–前682年在位。与鲁多次交战，乘丘之役鲁擒南宫万后释归；因猎博与万争执，前682年为南宫长万所弑于蒙泽。万立子游，诸公子杀子游而立弟御说为宋桓公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋闵公"}]','湣公',NULL,'宋湣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r17','游','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南宫长万弑闵公后立公子游，旋即为诸公子攻杀，在位仅数月，宋国政局再度动荡，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/游"}]',NULL,NULL,'游','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r18','御说','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','闵公弟御说杀子游自立，谥桓公，会盟诸侯、援齐灭郕，使宋国在春秋初年渐成东方强国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋桓公"}]','桓公',NULL,'宋桓公','[]');
