INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r26','佐','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','平公之子佐，谥元公，前517年欲乐氏融通晋援，遭华氏之党攻杀，在位约十四年，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋元公"}]','元公',NULL,'宋元公','[]');
