INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r7','举','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','纠弑厉公后立，谥釐公，在位约二十八年，复正嫡系，为宋国西周后期重要世君，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋釐公"}]','釐公',NULL,'宋釐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r8','覵','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','釐公之子，谥惠公，在位三十余年，属西周晚期宋国君主，事迹除世次外记载有限，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋惠公"}]','惠公',NULL,'宋惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-r9','','song-chunqiu','[]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠公之子，谥哀公，在位仅一年即卒，为宋国世系中罕见的极短祚君主，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋哀公"},{"label":"《史记·宋微子世家》","url":"https://zh.wikisource.org/wiki/史記/卷038"}]','哀公',NULL,'宋哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('song-weizi','启','song-chunqiu','["微子","微子启"]','子','宋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','微子启，帝乙长子、帝辛庶兄。数谏不听而亡奔，周封之于宋，为宋国始封君。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/微子"}]',NULL,NULL,'微子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuang-zhou','庄子','song-chunqiu','[]',NULL,NULL,-369,1,NULL,'year',-286,1,NULL,'year','["思想家"]','战国宋国蒙人，名周，道家思想家。曾任漆园吏，拒绝楚威王聘相；其思想与寓言主要见于后世编定的《庄子》，强调顺应自然、逍遥自适。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庄子"}]',NULL,NULL,NULL,'[]');
