INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('song-yan-assumes-kingship','宋君偃称王','politics','point','year',NULL,NULL,'《资治通鉴》周慎靓王三年记宋初称王；《史记》以君偃十一年叙述称王，其即位及称王绝对纪年有异说，采用前318年系年。',-318,12,NULL,-3793,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-318年，宋君偃采用王号，宋由公称转入称王阶段。此前君偃逐兄剔成而取得国君之位，诸强国相继称王后，他也以王号宣示地位。此后宋攻伐齐、楚、魏等邻国，扩张领土并力求强盛，最终引起诸强国干预；称王并未使宋摆脱夹处大国之间的处境。',NULL,NULL,'[{"label":"《资治通鉴》卷3","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷003"},{"label":"《史记·宋微子世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷038"}]');
